1	<!doctype html>
2	<html lang="zh-CN">
3	<meta charset="utf-8">
4	<meta name="viewport" content="width=device-width,initial-scale=1">
5	<title>ScoreArena · 桌面规则游戏与赛事管理</title>
6	<style>
7	  :root { color-scheme: light; }
8	  body { font-family: system-ui, sans-serif; max-width: 52rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }
9	  h1 { margin-bottom: .25rem; }
10	  .sub { color: #52606d; margin-top: 0; }
11	  h2 { margin-top: 2.5rem; border-bottom: 1px solid #e4e7eb; padding-bottom: .35rem; }
12	  a { color: #175b9c; }
13	  form { background: #f8f9fb; border: 1px solid #e4e7eb; border-radius: .5rem; padding: 1.25rem 1.5rem; }
14	  .field { display: grid; grid-template-columns: 9rem 1fr; gap: .75rem; align-items: center; margin-bottom: 1rem; }
15	  label { font-weight: 600; }
16	  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #cbd2d9; border-radius: .35rem; background: #fff; }
17	  input:focus, select:focus { outline: 2px solid #9ec5fe; outline-offset: 1px; border-color: #175b9c; }
18	  .hint { grid-column: 2; color: #616e7c; font-size: .9rem; margin: -.35rem 0 0; }
19	  .actions { grid-column: 2; margin-top: .25rem; }
20	  button { font: inherit; font-weight: 600; padding: .5rem 1.4rem; border: none; border-radius: .35rem; background: #175b9c; color: #fff; cursor: pointer; }
21	  button:disabled { background: #9aa5b1; cursor: wait; }
22	  .msg { margin: 1rem 0 0; padding: .6rem .9rem; border-radius: .35rem; display: none; }
23	  .msg.show { display: block; }
24	  .msg.error { background: #fde8e8; border: 1px solid #f5b5b5; color: #9b1c1c; }
25	  .msg.ok { background: #e6f6ec; border: 1px solid #a7e0bd; color: #146134; }
26	  table { width: 100%; border-collapse: collapse; font-size: .95rem; }
27	  th, td { text-align: left; padding: .55rem .6rem; border-bottom: 1px solid #e4e7eb; vertical-align: top; }
28	  th { color: #52606d; font-size: .85rem; white-space: nowrap; }
29	  td.id, code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .85rem; word-break: break-all; }
30	  .empty { color: #616e7c; }
31	  .skip-notice { background: #fff8e6; border: 1px solid #f0d48a; color: #7c4a03; padding: .6rem .9rem; border-radius: .35rem; margin: 0 0 1rem; }
32	  .list-error { color: #9b1c1c; }
33	  .badge { display: inline-block; padding: .05rem .55rem; border-radius: 999px; background: #fff3c4; color: #7c4a03; font-size: .85rem; }
34	  .meta { color: #7b8794; font-size: .85rem; }
35	</style>
36	<main>
37	  <h1>ScoreArena</h1>
38	  <p class="sub">桌面规则游戏与赛事管理</p>
39	
40	  <h2>创建公开房间</h2>
41	  <form id="room-form" novalidate>
42	    <div class="field">
43	      <label for="name">房间名称</label>
44	      <input id="name" name="name" type="text" autocomplete="off"
45	             placeholder="1–40 个字符，首尾空白会被去掉" required>
46	      <p class="hint">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。原始输入不限长，整理后不超过 40 个字符即可。</p>
47	    </div>
48	    <div class="field">
49	      <label for="game">游戏规则</label>
50	      <select id="game" name="game" required>
51	        <option value="" selected>请选择游戏规则…</option>
52	        <option value="gomoku">五子棋（gomoku）</option>
53	        <option value="ludo">飞行棋（ludo）</option>
54	      </select>
55	    </div>
56	    <div class="field">
57	      <label for="capacity">人数上限</label>
58	      <select id="capacity" name="capacity" required disabled>
59	        <option value="" selected>请先选择游戏规则</option>
60	      </select>
61	      <p class="hint" id="capacity-hint">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>
62	    </div>
63	    <div class="field">
64	      <label for="turnSeconds">每步时间限制</label>
65	      <input id="turnSeconds" name="turnSeconds" type="number" step="1" inputmode="numeric"
66	             placeholder="秒，0 表示不限时" required>
67	      <p class="hint">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>
68	    </div>
69	    <div class="field">
70	      <div></div>
71	      <div class="actions">
72	        <button type="submit" id="submit">创建房间</button>
73	      </div>
74	    </div>
75	    <p class="msg" id="form-msg" role="alert"></p>
76	  </form>
77	
78	  <h2>房间列表</h2>
79	  <div id="list-area">
80	    <p class="empty" id="empty-tip">还没有房间记录。</p>
81	  </div>
82	
83	  <p class="meta"><a href="/api/rooms">查看房间列表接口</a> · <a href="/health">服务状态</a></p>
84	</main>
85	
86	<script>
87	(function () {
88	  var form = document.getElementById('room-form');
89	  var gameSel = document.getElementById('game');
90	  var capSel = document.getElementById('capacity');
91	  var capHint = document.getElementById('capacity-hint');
92	  var submitBtn = document.getElementById('submit');
93	  var formMsg = document.getElementById('form-msg');
94	  var listArea = document.getElementById('list-area');
95	  var emptyTip = document.getElementById('empty-tip');
96	
97	  // 映射表必须是无原型对象：历史值里可能恰好存着 "constructor"、"toString"、
98	  // "__proto__" 这类字符串，普通对象字面量会沿原型链查到内置函数或
99	  // Object.prototype，反而把函数源码或 [object Object] 当成中文映射显示。
100	  // 无原型对象查这些键一律得到 undefined，于是按未知值逐字回显原文。
101	  var GAME_LABELS = Object.create(null);
102	  GAME_LABELS.gomoku = '五子棋';
103	  GAME_LABELS.ludo = '飞行棋';
104	  var STATUS_LABELS = Object.create(null);
105	  STATUS_LABELS.waiting = '未开始';
106	
107	  // 按所选规则重建人数上限选项。
108	  function syncCapacity() {
109	    var game = gameSel.value;
110	    var prev = capSel.value;
111	    capSel.innerHTML = '';
112	    if (game === 'gomoku') {
113	      capSel.disabled = false;
114	      addOption('', '固定 2 人');
115	      addOption('2', '2 人');
116	      capSel.value = '2';
117	      capHint.textContent = '五子棋人数上限固定为 2 人。';
118	    } else if (game === 'ludo') {
119	      capSel.disabled = false;
120	      addOption('', '请选择人数上限…');
121	      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });
122	      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';
123	      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';
124	    } else {
125	      capSel.disabled = true;
126	      addOption('', '请先选择游戏规则');
127	      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';
128	    }
129	  }
130	
131	  function addOption(value, text) {
132	    var opt = document.createElement('option');
133	    opt.value = value;
134	    opt.textContent = text;
135	    capSel.appendChild(opt);
136	  }
137	
138	  gameSel.addEventListener('change', syncCapacity);
139	
140	  function showMessage(kind, text) {
141	    formMsg.className = 'msg show ' + kind;
142	    formMsg.textContent = text;
143	  }
144	  function clearMessage() {
145	    formMsg.className = 'msg';
146	    formMsg.textContent = '';
147	  }
148	
149	  // 与服务端 strings.TrimSpace（Go unicode.IsSpace）完全一致的首尾空白范围：
150	  // 包含 U+0085、U+00A0 等，但不包含 U+FEFF（保留并计入长度）。
151	  // 不能用 JS 自带的 trim()：它会多去掉 U+FEFF，又漏掉 U+0085。
152	  var EDGE_SPACE = '[\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]';
153	  var LEADING_SPACE = new RegExp('^' + EDGE_SPACE + '+');
154	  var TRAILING_SPACE = new RegExp(EDGE_SPACE + '+$');
155	  function trimName(value) {
156	    return value.replace(LEADING_SPACE, '').replace(TRAILING_SPACE, '');
157	  }
158	
159	  // 与服务端一致的提交前校验；服务端仍会再次校验。
160	  // 输入表单原始值，返回 { error } 或 { payload }：漏填要明确报错，绝不补默认值；
161	  // 名称只含会被去掉的首尾空白时同样视为空。通过校验的 payload 中名称仍是
162	  // 用户原始输入（不由页面整理），时间与人数各只转换一次。
163	  function checkForm(raw) {
164	    var nameLen = Array.from(trimName(raw.name)).length;
165	    if (nameLen === 0) return { error: '房间名称不能为空。' };
166	    if (!raw.game) return { error: '请选择游戏规则。' };
167	    if (raw.capacity === '') return { error: '请选择人数上限。' };
168	    if (raw.turnSeconds === '') return { error: '请填写每步时间限制（0 表示不限时）。' };
169	    if (!/^-?\d+$/.test(raw.turnSeconds)) return { error: '时间限制必须是整数秒，不能含小数。' };
170	
171	    // 通过必填与整数格式检查后再转换：空值不会变成 0，不合法文字不会变成秒数。
172	    var capacity = parseInt(raw.capacity, 10);
173	    var turnSeconds = Number(raw.turnSeconds);
174	
175	    if (nameLen > 40) return { error: '房间名称去掉首尾空白后不能超过 40 个字符。' };
176	    if (raw.game !== 'gomoku' && raw.game !== 'ludo') return { error: '请选择游戏规则。' };
177	    if (raw.game === 'gomoku' && capacity !== 2) return { error: '五子棋的人数上限固定为 2 人。' };
178	    if (raw.game === 'ludo' && !(capacity >= 2 && capacity <= 4)) {
179	      return { error: '飞行棋的人数上限必须为 2 至 4 人。' };
180	    }
181	    if (turnSeconds !== 0 && !(turnSeconds >= 10 && turnSeconds <= 600)) {
182	      return { error: '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。' };
183	    }
184	
185	    return {
186	      payload: {
187	        name: raw.name,
188	        game: raw.game,
189	        capacity: capacity,
190	        turnSeconds: turnSeconds
191	      }
192	    };
193	  }
194	
195	  form.addEventListener('submit', function (event) {
196	    event.preventDefault();
197	    clearMessage();
198	
199	    var result = checkForm({
200	      name: document.getElementById('name').value,
201	      game: gameSel.value,
202	      capacity: capSel.value,
203	      turnSeconds: document.getElementById('turnSeconds').value.trim()
204	    });
205	    if (result.error) { showMessage('error', result.error); return; }
206	
207	    submit(result.payload);
208	  });
209	
210	  function submit(payload) {
211	    submitBtn.disabled = true;
212	    fetch('/api/rooms', {
213	      method: 'POST',
214	      headers: { 'Content-Type': 'application/json' },
215	      body: JSON.stringify(payload)
216	    }).then(function (resp) {
217	      return resp.json().catch(function () { return {}; }).then(function (data) {
218	        return { ok: resp.ok, status: resp.status, data: data };
219	      });
220	    }).then(function (result) {
221	      if (result.ok && result.status === 201) {
222	        showMessage('ok', '房间已创建，编号：' + result.data.id);
223	        form.reset();
224	        syncCapacity();
225	        return loadRooms();
226	      }
227	      // 创建失败：保留填写内容，仅显示原因。
228	      var reason = result.data && result.data.error ? result.data.error
229	                 : ('创建失败（HTTP ' + result.status + '）');
230	      showMessage('error', reason);
231	    }).catch(function () {
232	      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
233	    }).finally(function () {
234	      submitBtn.disabled = false;
235	    });
236	  }
237	
238	  // 创建时间列的三种正常展示（对象/数组已由 buildRoomRow 统一判为异常，
239	  // 不会进入这里）：
240	  //   1. 能解析成有效日期的字符串：按浏览器本地时区显示
241	  //      YYYY-MM-DD HH:mm:ss（带时区偏移的时间换算成实际对应的本地时刻，
242	  //      不把原串里的时分当本地时间），悬浮提示保留接口返回的原始字符串；
243	  //   2. 无法解析的非空字符串：原文直接显示在单元格中（textContent 保证
244	  //      尖括号等字符只作为文字呈现），不替换为当前时间，不附悬浮说明；
245	  //   3. 字段缺失、null 或空字符串：单元格留空且没有悬浮说明，
246	  //      绝不由页面生成 undefined 或 Invalid Date。
247	  function renderTimeCell(td, value) {
248	    if (value == null || value === '') return;
249	
250	    var d = new Date(value);
251	    if (isNaN(d.getTime())) {
252	      td.textContent = typeof value === 'string' ? value : String(value);
253	      return;
254	    }
255	
256	    var pad = function (n) { return String(n).padStart(2, '0'); };
257	    td.textContent = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
258	      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
259	    td.title = typeof value === 'string' ? value : String(value);
260	  }
261	
262	  // 只有 JSON 对象能作为房间行；null、字符串、数字、布尔值和数组都跳过。
263	  // 不按创建表单的规则重新判定历史记录：对象带多少附加字段都照常展示，
264	  // 也不检查其字段是否完整或合法（各单元格沿用现有兜底显示）。
265	  function isRoomRecord(value) {
266	    return value !== null && typeof value === 'object' && !Array.isArray(value);
267	  }
268	
269	  function appendSkipNotice(skipped, allSkipped) {
270	    var p = document.createElement('p');
271	    p.className = 'skip-notice';
272	    if (allSkipped) {
273	      p.textContent = '没有可展示的房间。本次返回的房间记录中有 ' + skipped +
274	        ' 条无法作为房间显示，已全部跳过；原始数据仍保留在服务端，未被删除或改写。';
275	    } else {
276	      p.textContent = '有 ' + skipped + ' 条房间记录无法作为房间显示，已跳过；' +
277	        '原始数据仍保留在服务端，未被删除或改写。';
278	    }
279	    listArea.appendChild(p);
280	  }
281	
282	  // 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示
283	  // “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出
284	  // 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算
285	  // 异常，仍走各列原有的展示与兜底。
286	  var BAD_FIELD_TEXT = '字段格式异常';
287	  function isAbnormalField(value) {
288	    return value !== null && typeof value === 'object';
289	  }
290	  function markBadCell(td) {
291	    td.textContent = BAD_FIELD_TEXT;
292	  }
293	
294	  function appendBadge(td, text) {
295	    var badge = document.createElement('span');
296	    badge.className = 'badge';
297	    badge.textContent = text;
298	    td.appendChild(badge);
299	  }
300	
301	  // 七列的展示定义，顺序即表格列顺序（表头也由同一份定义生成）。每列只
302	  // 描述“正常值如何显示”（含各列原有的兜底行为）；对象/数组的异常判定
303	  // 与替换由 buildRoomRow 统一处理，不在各列重复维护。个别列可用
304	  // renderBad 保留原有容器（如状态列的徽标），缺省时整格替换为异常文案。
305	  var ROOM_COLUMNS = [
306	    {
307	      key: 'id',
308	      label: '房间编号',
309	      className: 'id',
310	      render: function (td, value) { td.textContent = value || ''; }
311	    },
312	    {
313	      key: 'name',
314	      label: '名称',
315	      render: function (td, value) { td.textContent = value || ''; }
316	    },
317	    {
318	      key: 'game',
319	      label: '规则',
320	      render: function (td, value) {
321	        td.textContent = GAME_LABELS[value] || value || '';
322	      }
323	    },
324	    {
325	      key: 'capacity',
326	      label: '人数上限',
327	      render: function (td, value) {
328	        td.textContent = (value != null ? value : '') + ' 人';
329	      }
330	    },
331	    {
332	      key: 'turnSeconds',
333	      label: '时间限制',
334	      render: function (td, value) {
335	        td.textContent = value === 0 ? '不限时' : value + ' 秒';
336	      }
337	    },
338	    {
339	      key: 'status',
340	      label: '状态',
341	      render: function (td, value) {
342	        appendBadge(td, STATUS_LABELS[value] || value || '');
343	      },
344	      // 异常状态仍在原有徽标中显示提示文案。
345	      renderBad: function (td) { appendBadge(td, BAD_FIELD_TEXT); }
346	    },
347	    {
348	      key: 'createdAt',
349	      label: '创建时间',
350	      render: renderTimeCell
351	      // 无 renderBad：异常创建时间只显示异常文案，不附加日期悬浮说明
352	      // （不设置 title）。
353	    }
354	  ];
355	
356	  // 逐列渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。
357	  function buildRoomRow(r) {
358	    var tr = document.createElement('tr');
359	    ROOM_COLUMNS.forEach(function (col) {
360	      var td = document.createElement('td');
361	      if (col.className) td.className = col.className;
362	      var value = r[col.key];
363	      if (isAbnormalField(value)) {
364	        if (col.renderBad) col.renderBad(td);
365	        else markBadCell(td);
366	      } else {
367	        col.render(td, value);
368	      }
369	      tr.appendChild(td);
370	    });
371	    return tr;
372	  }
373	
374	  function renderRooms(rooms) {
375	    listArea.innerHTML = '';
376	
377	    var validRooms = [];
378	    var skipped = 0;
379	    rooms.forEach(function (r) {
380	      if (isRoomRecord(r)) validRooms.push(r);
381	      else skipped++;
382	    });
383	
384	    if (!validRooms.length) {
385	      if (skipped > 0) {
386	        appendSkipNotice(skipped, true);
387	      } else {
388	        var pEmpty = document.createElement('p');
389	        pEmpty.className = 'empty';
390	        pEmpty.textContent = '还没有房间记录。';
391	        listArea.appendChild(pEmpty);
392	      }
393	      return;
394	    }
395	
396	    if (skipped > 0) appendSkipNotice(skipped, false);
397	
398	    var table = document.createElement('table');
399	    var thead = document.createElement('thead');
400	    var headRow = document.createElement('tr');
401	    ROOM_COLUMNS.forEach(function (col) {
402	      var th = document.createElement('th');
403	      th.textContent = col.label;
404	      headRow.appendChild(th);
405	    });
406	    thead.appendChild(headRow);
407	    table.appendChild(thead);
