183	// 所有字段都必须明确提交且合法，不使用任何默认值。
184	func validateConfig(cfg roomConfig) (int, string, bool) {
185		name := strings.TrimSpace(cfg.Name)
186		if name == "" {
187			return http.StatusBadRequest, "房间名称不能为空", false
