	Game        string `json:"game"`
	Capacity    int    `json:"capacity"`
	TurnSeconds int    `json:"turnSeconds"`
}

type room struct {
	ID          string `json:"id"`
	Name        string `json:"name"`
	Game        string `json:"game"`
	Capacity    int    `json:"capacity"`
	TurnSeconds int    `json:"turnSeconds"`
	Status      string `json:"status"`
	Visibility  string `json:"visibility"`
	CreatedAt   string `json:"createdAt"`
}

